package edu.ankara.audiometer.infrastructure.serial;
import edu.ankara.audiometer.domain.fp.Result;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
public final class FakeSerialGateway implements SerialPortGateway { private SerialConnectionStatus status=SerialConnectionStatus.disconnected(); private Consumer<String> onLine=s->{}; private final List<String> sent=new CopyOnWriteArrayList<>(); public List<String> sentCommands(){return List.copyOf(sent);} public List<String> listPorts(){return List.of("SIMULATED-COM");} public Result<SerialConnectionStatus,String> connect(String port,int baudRate,Consumer<String> onLine){this.onLine=onLine; status=new SerialConnectionStatus(true,port,"Simulation connected at "+baudRate); return Result.ok(status);} public Result<Void,String> disconnect(){status=SerialConnectionStatus.disconnected(); return Result.ok(null);} public Result<Void,String> send(String command){ if(!status.connected()) return Result.err("Fake serial is disconnected"); sent.add(command); return Result.ok(null);} public void injectLine(String line){onLine.accept(line);} public SerialConnectionStatus status(){return status;} }
